  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Ketanserin, which shares the 4-fluorophenyl ketone, piperidine, and fused heterocyclic dione core with the query, has an absolute oral bioavailability of 50.4±6.2% in healthy male subjects, directly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Sertindole, a piperidine-containing antipsychotic with a fluorophenyl group and imidazolidinone, has an oral bioavailability of 75% in patients, supporting high F for this CNS drug class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Trazodone, a structurally related CNS drug with a piperazine/heteroaromatic system, has an absolute oral bioavailability of 63±4% in fasting healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Maraviroc, a piperidine-containing drug with substantial first-pass metabolism, still achieves an absolute oral bioavailability of 33% at a 300 mg dose, confirming that even lower-F piperidine drugs remain above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query (benperidol) is a butyrophenone antipsychotic with a 4-fluorophenyl ketone, piperidine, and benzimidazolone. Multiple high-transfer human absolute bioavailability records for structurally related CNS drugs (ketanserin ~50%, sertindole ~75%, trazodone 63-91%, cerivastatin 60%) consistently show F ≥20%, often well above. Even the lowest relevant piperidine-containing drug (maraviroc) is 23-33%, still above threshold. No affirmative evidence supports F<20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct benperidol absolute bioavailability measurement is present in the evidence set.",
    "First-pass metabolism and interindividual variability (e.g., encainide range 7-82%) could affect the query, but no query-specific metabolic data are available.",
    "Transfer scores are high but based on analogue molecules rather than the identical compound."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

